datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int       @id @default(autoincrement())
  username String    @unique
  comments Comment[]
}

model Post {
  id       Int       @id @default(autoincrement())
  title    String
  comments Comment[]
}

model Comment {
  id             Int       @id @default(autoincrement())
  content        String
  post           Post      @relation(fields: [postId], references: [id], onDelete: Cascade)
  postId         Int
  author         User      @relation(fields: [authorId], references: [id], onDelete: Cascade)
  authorId       Int
  parent         Comment?  @relation("CommentReplies", fields: [parentId], references: [id], onDelete: Cascade)
  parentId       Int?
  children       Comment[] @relation("CommentReplies")
}

app nestedComments {
  wasp: {
    version: "^0.16.8"
  },
  title: "nested-comments",
  db: {
    seeds: [
      import { devSeed } from "@src/seeds"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

route PostRoute { path: "/post/:postId", to: PostPage }
page PostPage {
  component: import { PostPage } from "@src/PostPage"
}

query getPosts {
  fn: import { getPosts } from "@src/queries",
  entities: [Post]
}

query getCommentTree {
  fn: import { getCommentTree } from "@src/queries",
  entities: [Comment, Post]
}

action createComment {
  fn: import { createComment } from "@src/actions",
  entities: [Comment, Post, User]
}

action deleteComment {
  fn: import { deleteComment } from "@src/actions",
  entities: [Comment]
}

export const getPosts = async (args, context) => {
  return context.entities.Post.findMany({
    select: {
      id: true,
      title: true,
    },
  });
};

export const getCommentTree = async (args, context) => {
  const comments = await context.entities.Comment.findMany({
    where: { postId: args.postId },
    include: {
      author: true,
    },
    orderBy: {
      id: 'asc',
    },
  });

  const nodesMap = {};
  for (const comment of comments) {
    nodesMap[comment.id] = {
      id: comment.id,
      content: comment.content,
      authorUsername: comment.author.username,
      parentId: comment.parentId,
      children: [],
    };
  }

  const rootNodes = [];
  for (const comment of comments) {
    const node = nodesMap[comment.id];
    if (comment.parentId === null) {
      rootNodes.push(node);
    } else {
      const parentNode = nodesMap[comment.parentId];
      if (parentNode) {
        parentNode.children.push(node);
      }
    }
  }

  return rootNodes;
};

export const createComment = async (args, context) => {
  const user = await context.entities.User.findUnique({
    where: { username: args.authorUsername },
  });
  if (!user) {
    throw new Error(`User with username ${args.authorUsername} not found`);
  }

  const comment = await context.entities.Comment.create({
    data: {
      content: args.content,
      postId: args.postId,
      authorId: user.id,
      parentId: args.parentId || null,
    },
  });

  return comment;
};

export const deleteComment = async (args, context) => {
  const deleteRecursive = async (commentId) => {
    const children = await context.entities.Comment.findMany({
      where: { parentId: commentId },
      select: { id: true },
    });
    for (const child of children) {
      await deleteRecursive(child.id);
    }
    await context.entities.Comment.delete({
      where: { id: commentId },
    });
  };

  await deleteRecursive(args.commentId);
};

export const devSeed = async (prisma) => {
  await prisma.user.upsert({
    where: { username: 'alice' },
    update: {},
    create: { username: 'alice' },
  });

  await prisma.user.upsert({
    where: { username: 'bob' },
    update: {},
    create: { username: 'bob' },
  });

  const existingPost = await prisma.post.findFirst({
    where: { title: 'Wasp Nested Comments' },
  });

  if (!existingPost) {
    await prisma.post.create({
      data: { title: 'Wasp Nested Comments' },
    });
  }
};

